export function projectCoord([lng, lat]: [number, number]): [number, number] {
  if (lat > 50.5 || (lng < -130 && lat > 50)) {
    const adjLng = lng > 0 ? lng - 360 : lng;
    const x = (adjLng - (-172)) * 3.1 + 42;
    const y = 635 - (lat - 52) * 5.8;
    return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
  }
  if (lng < -150 && lat < 25) {
    const x = (lng - (-160.5)) * 18.0 + 235;
    const y = 632 - (lat - 18.8) * 18.0;
    return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
  }
  const lon0 = -96.0;
  const lat0 = 37.5;
  const deg2rad = Math.PI / 180;
  const phi1 = 29.5 * deg2rad;
  const phi2 = 45.5 * deg2rad;
  const phi0 = lat0 * deg2rad;
  const lambda0 = lon0 * deg2rad;
  const phi = lat * deg2rad;
  const lambda = lng * deg2rad;

  const n = 0.5 * (Math.sin(phi1) + Math.sin(phi2));
  const C = Math.cos(phi1) * Math.cos(phi1) + 2 * n * Math.sin(phi1);
  const rho0 = Math.sqrt(C - 2 * n * Math.sin(phi0)) / n;
  const rho = Math.sqrt(C - 2 * n * Math.sin(phi)) / n;
  const theta = n * (lambda - lambda0);

  const rawX = rho * Math.sin(theta);
  const rawY = rho0 - rho * Math.cos(theta);

  const scale = 1080;
  const cx = 485;
  const cy = 305;

  const x = cx + rawX * scale;
  const y = cy - rawY * scale;
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
}
